/* ===== Lifestyle Carousel ===== */
.carousel {
  padding: 80px 0;
  background: var(--black-light);
  overflow: hidden;
}
.carousel__header {
  text-align: center;
  margin-bottom: 48px;
}
.carousel__track-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
}
.carousel__track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel__slide {
  min-width: 100%;
  aspect-ratio: 16 / 9;
  background: var(--gray-dark);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel__slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.carousel__slide-placeholder {
  font-family: var(--font-head);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray);
}
.carousel__slide-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 24px;
  background: linear-gradient(to top, rgba(0,0,0,0.7), transparent);
}
.carousel__slide-overlay span {
  font-family: var(--font-head);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.carousel__btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
