  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition);
  border-radius: 4px;
}
.carousel__btn:hover { background: var(--red); border-color: var(--red); }
.carousel__btn--prev { left: 12px; }
.carousel__btn--next { right: 12px; }
.carousel__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}
.carousel__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-dark);
  cursor: pointer;
  transition: all var(--transition);
  border: none;
}
.carousel__dot.active { background: var(--red); transform: scale(1.2); }

